import{_ as t}from"./chunks/locator-healing.BjNtRxlF.js";import{_ as a,o as i,c as s,ak as o}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Fix a broken locator","description":"","frontmatter":{"title":"Fix a broken locator","lang":"en-US"},"headers":[],"relativePath":"recipes/broken-locator.md","filePath":"recipes/broken-locator.md","lastUpdated":1788683522000}'),n={name:"recipes/broken-locator.md"};function r(h,e,l,p,c,d){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="a-locator-broke-after-a-ui-change-—-what-should-i-use-instead" tabindex="-1">A locator broke after a UI change — what should I use instead? <a class="header-anchor" href="#a-locator-broke-after-a-ui-change-—-what-should-i-use-instead" aria-label="Permalink to &quot;A locator broke after a UI change — what should I use instead?&quot;">​</a></h1><p>Someone renamed a button, moved a <code>data-testid</code>, or wrapped a row in one more <code>div</code>, and a handful of tests now fail on <code>locator.click: Timeout … waiting for getByRole(&#39;button&#39;, { name: &#39;Save&#39; })</code>. The fix is rarely hard; finding a replacement that won&#39;t break again next sprint is the actual work.</p><p>Piwi captures what the element looked like <strong>on the last run where the test passed</strong>, so the replacement is proposed from a page that worked rather than from the broken one in front of you.</p><h2 id="_1-open-the-failing-execution-s-alternative-locators" tabindex="-1">1. Open the failing execution&#39;s alternative locators <a class="header-anchor" href="#_1-open-the-failing-execution-s-alternative-locators" aria-label="Permalink to &quot;1. Open the failing execution&#39;s alternative locators&quot;">​</a></h2><p>On a failing test case, the <strong>Alternative locators</strong> panel lists candidate replacements ranked by stability, with one marked as the recommended fix.</p><figure><img src="'+t+`" alt="Alternative locators panel with ranked replacement locators and a recommended fix"><figcaption>Ranked replacements captured from the last passing run — the recommendation favours locators that match the conventions already in your suite.</figcaption></figure><p>The ranking prefers what Playwright itself prefers — role and test-id over structural CSS — and leans toward the style your existing specs already use, so the suggestion doesn&#39;t drag a second convention into the codebase.</p><h2 id="_2-jump-to-the-line-and-change-it" tabindex="-1">2. Jump to the line and change it <a class="header-anchor" href="#_2-jump-to-the-line-and-change-it" aria-label="Permalink to &quot;2. Jump to the line and change it&quot;">​</a></h2><p>Every source path in the dashboard is clickable, including the failing call stack. Hover the path and use <strong>open in IDE</strong> to land on the exact line. That mapping is configured <a href="./../ide-integration.html">per browser</a> and stored locally — your checkout path is never sent to the server.</p><p>No IDE integration set up? The path and line number are plain text on the page; the fastest route is usually copying them.</p><h2 id="shortcut-if-it-broke-on-your-machine-fix-it-before-the-browser-closes" tabindex="-1">Shortcut: if it broke on your machine, fix it before the browser closes <a class="header-anchor" href="#shortcut-if-it-broke-on-your-machine-fix-it-before-the-browser-closes" aria-label="Permalink to &quot;Shortcut: if it broke on your machine, fix it before the browser closes&quot;">​</a></h2><p>Everything above assumes the failure is already in the dashboard. When you&#39;re running locally, there&#39;s a faster path — pause on the failing page and pick the replacement from the live DOM, while the app is still in the state that broke it.</p><p>Two reporter options, both off by default:</p><table tabindex="0"><thead><tr><th>Option</th><th>Env var</th><th>Opens</th></tr></thead><tbody><tr><td><code>pickLocatorOnFailure</code></td><td><code>PIWI_PICK_LOCATOR_ON_FAIL</code></td><td>the picker, aimed at the locator that just broke</td></tr><tr><td><code>inspectOnFailure</code></td><td><code>PIWI_INSPECT_ON_FAIL</code></td><td>the same overlay, but free to inspect any element on the page</td></tr></tbody></table><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  serverUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://localhost:3000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  projectName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-project&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  pickLocatorOnFailure: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre></div><p>The run <strong>pauses</strong> with the failing page still open — the test timeout is lifted while the overlay is up — and you click the element you meant. Piwi generates ranked, uniqueness-checked candidates, and the one you confirm is recorded as a pick: it comes back in the dashboard with a <strong>Your pick</strong> badge and becomes the recommended fix. It works for a broken action (<code>.click()</code>, <code>.fill()</code>) and for a failed assertion (<code>expect(locator).toBeVisible()</code>), reading the locator from Playwright&#39;s own error in the latter case.</p><p>This is Piwi&#39;s own overlay, not Playwright&#39;s inspector, which is why what you confirm flows back into the healing data instead of just into your clipboard.</p><p>Worth knowing before you switch it on:</p><ul><li>It needs a <strong>headed</strong> browser (<code>--headed</code>, or <code>headless: false</code>), and it <strong>never activates under CI</strong> — any <code>CI</code> env var disables it.</li><li>With retries configured it only opens on the final attempt, and it skips expected failures (<code>test.fail()</code>).</li><li>Because the run waits while the overlay is open, use <code>--workers=1</code> or your other workers sit idle.</li><li><strong>It never rewrites your test.</strong> It records the choice; applying it is still your edit.</li></ul><h2 id="requirements-honestly" tabindex="-1">Requirements, honestly <a class="header-anchor" href="#requirements-honestly" aria-label="Permalink to &quot;Requirements, honestly&quot;">​</a></h2><p>Locator healing needs the <a href="./../capture-fixtures.html">capture fixtures</a> in your test setup. The reporter alone uploads results without touching your test code, but it cannot see the DOM — the ranked alternatives come from <a href="./../concepts.html#locator-snapshot">locator snapshots</a> the fixtures record while the test runs.</p><p>It is one file:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tests/fixtures.ts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { test </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@playwright/test&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { extendPiwiFixtures } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@piwitests/reporter&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> test</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> extendPiwiFixtures</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { expect } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@playwright/test&#39;</span></span></code></pre></div><p>Import <code>test</code> from that file in your specs. A spec that still imports from <code>@playwright/test</code> directly runs and reports fine — it just isn&#39;t captured.</p><p>Snapshots are only recorded going forward, so the first healing suggestions appear once a passing run has been captured with the fixtures in place.</p><h2 id="if-you-can-t-add-the-fixtures" tabindex="-1">If you can&#39;t add the fixtures <a class="header-anchor" href="#if-you-can-t-add-the-fixtures" aria-label="Permalink to &quot;If you can&#39;t add the fixtures&quot;">​</a></h2><p>Some suites can&#39;t take the code change — a vendored test pack, a repo you don&#39;t own, a migration you don&#39;t want mid-release. Four routes that don&#39;t need it:</p><p><strong>Pick from the trace, after the fact.</strong> When the failing execution has an uploaded trace, the alternative-locators panel offers <strong>Pick from trace</strong>: it opens the trace in the dashboard&#39;s bundled <a href="./../evidence.html#trace-viewer">trace viewer</a>, whose <em>Pick locator</em> tool works on the recorded page snapshots. So a CI failure nobody watched live can still be picked visually, days later, from the page as it actually was.</p><p><strong>Pick against the live page.</strong> The <a href="./../extension.html">browser extension</a> scores locators with the same engine the dashboard uses, directly on the page you&#39;re looking at. Picking and recording are fully standalone — nothing is sent anywhere, and it works without a Piwi instance at all. The cost: one click from the <a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Chrome Web Store</a>, which is also how you install it in Edge.</p><p><strong>Read the failure evidence you already have.</strong> Without fixtures you still get the trace, the screenshot, and the failing call stack. Playwright&#39;s trace viewer is bundled and served by your own instance — the DOM snapshot at the moment of failure usually shows what the element became.</p><p><strong>Ask your agent.</strong> <code>get_locator_healing</code> over the <a href="./../mcp.html">MCP server</a> returns the recommended fix and the full alternatives list for a failing case, so a coding agent can apply it without you opening the dashboard. This one does still depend on captured snapshots — it reads the same data the panel does.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../capture-fixtures.html">Capture fixtures</a> — everything else the fixtures unlock</li><li><a href="./../locator-healing.html">Reporter</a> — configuration and how the scoring works</li><li><a href="./../locator-healing.html#inspect-the-failing-page-live-local-runs">Reporter → Inspect the failing page live</a> — the full reference for the pause-on-failure options</li><li><a href="./../extension.html">Browser extension</a> — picking and recording locators against a live page</li></ul>`,33)])])}const f=a(n,[["render",r]]);export{g as __pageData,f as default};
